        --color-error-bg:     #fef2f2;
        --color-error-border: #fca5a5;
        --color-success:      #15803d;
        --color-success-bg:   #f0fdf4;
        --color-success-border:#86efac;
        --radius-sm:          6px;
        --radius-md:          10px;
        --radius-lg:          16px;
        --shadow-card:        0 1px 3px rgba(0,0,0,.08), 0 4px 16px rgba(0,0,0,.06);
        --font-sans:          -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto,
                              Helvetica, Arial, sans-serif;
      }

      /* ── Skip link ── */
      .skip-link {
        position: absolute;
        top: -100%;
        left: 1rem;
        padding: .5rem 1rem;
        background: var(--color-primary);
        color: #fff;
        border-radius: var(--radius-sm);
        font-weight: 600;
        font-family: var(--font-sans);
        text-decoration: none;
        z-index: 100;
        transition: top .15s;
      }
      .skip-link:focus { top: 1rem; }

      /* ── Layout ── */
      body {
        min-height: 100vh;
        display: flex;
        flex-direction: column;
        background: var(--color-bg);
        font-family: var(--font-sans);
        color: var(--color-text);
        line-height: 1.6;
      }

      header {
        padding: 1.25rem 1.5rem;
        background: var(--color-surface);
        border-bottom: 1px solid var(--color-border);
      }
      .brand {
        font-size: 1.125rem;
        font-weight: 700;
        letter-spacing: -.02em;
        color: var(--color-text);
        text-decoration: none;
      }

      main {
        flex: 1;
        display: flex;
        align-items: center;
        justify-content: center;
        padding: 2.5rem 1rem;
      }

      /* ── Card ── */
      .card {
        background: var(--color-surface);
        border-radius: var(--radius-lg);
        box-shadow: var(--shadow-card);
        padding: 2.5rem 2rem;
        width: 100%;
        max-width: 480px;
      }

      .card-header { margin-bottom: 1.75rem; }
      .card-header h1 {
        font-size: 1.5rem;
        font-weight: 700;
        letter-spacing: -.03em;
        line-height: 1.25;
        margin-bottom: .5rem;
      }
      .card-header p {
        font-size: .9375rem;
        color: var(--color-text-muted);
      }

      /* Required legend */
      .required-legend {
        font-size: .8125rem;
        color: var(--color-text-muted);
        margin-bottom: 1.5rem;
      }
      .required-legend span[aria-hidden] { color: var(--color-error); }

      /* ── Form field ── */
      .form-field {
        display: flex;
        gap: .875rem;
        padding: 1.125rem 1rem;
        border: 1.5px solid var(--color-border);
        border-radius: var(--radius-md);
        background: #fafafa;
        transition: border-color .15s;
      }
      .form-field:focus-within { border-color: var(--color-border-focus); }
      .form-field.is-invalid {
        border-color: var(--color-error-border);
        background: var(--color-error-bg);
      }

      /* Custom checkbox */
      .form-field input[type="checkbox"] {
        appearance: none;
        -webkit-appearance: none;
        flex-shrink: 0;
        width: 1.25rem;
        height: 1.25rem;
        margin-top: .1875rem;
        border: 2px solid var(--color-border);
        border-radius: 4px;
        background: #fff;
        cursor: pointer;
        transition: border-color .15s, background-color .15s, box-shadow .15s;
        position: relative;
      }
      .form-field input[type="checkbox"]:checked {
        background: var(--color-primary);
        border-color: var(--color-primary);
      }
      .form-field input[type="checkbox"]:checked::after {
        content: "";
        position: absolute;
        top: 2px; left: 5px;
        width: 5px; height: 9px;
        border: 2px solid #fff;
        border-top: none;
        border-left: none;
        transform: rotate(45deg);
      }
      .form-field input[type="checkbox"]:focus-visible {
        outline: 3px solid var(--color-border-focus);
        outline-offset: 2px;
        border-color: var(--color-border-focus);
        box-shadow: 0 0 0 4px rgba(37,99,235,.15);
      }

      .form-field label {
        font-size: .9375rem;
        font-weight: 500;
        cursor: pointer;
        line-height: 1.5;
      }
      .form-field label a {
        color: var(--color-primary);
        text-decoration: underline;
        text-underline-offset: 2px;
      }
      .form-field label a:hover  { color: var(--color-primary-dark); }
      .form-field label a:focus-visible {
        outline: 2px solid var(--color-border-focus);
        outline-offset: 2px;
        border-radius: 2px;
      }

      .required-star {
        color: var(--color-error);
        margin-left: .125rem;
      }

      /* Helper text */
      .field-helper {
        font-size: .8125rem;
        color: var(--color-text-muted);
        margin-top: .375rem;
        padding-left: calc(1rem + 1.25rem + .875rem); /* card-pad + checkbox + gap */
      }

      /* Error message */
      .field-error {
        display: flex;
        align-items: flex-start;
        gap: .375rem;
        font-size: .875rem;
        color: var(--color-error);
        font-weight: 500;
        margin-top: .5rem;
        padding-left: calc(1rem + 1.25rem + .875rem);
      }
      .field-error svg { flex-shrink: 0; margin-top: .125rem; }

      /* ── Submit button ── */
      .btn-submit {
        display: block;
        width: 100%;
        margin-top: 1.75rem;
        padding: .8125rem 1.5rem;
        background: var(--color-primary);
        color: #fff;
        font-family: var(--font-sans);
        font-size: 1rem;
        font-weight: 600;
        border: none;
        border-radius: var(--radius-md);
        cursor: pointer;
        transition: background-color .15s, transform .1s, box-shadow .15s;
        letter-spacing: -.01em;
      }
      .btn-submit:hover  { background: var(--color-primary-dark); }
      .btn-submit:active { transform: scale(.985); }
      .btn-submit:focus-visible {
        outline: 3px solid var(--color-border-focus);
        outline-offset: 2px;
        box-shadow: 0 0 0 4px rgba(37,99,235,.2);
      }

      /* ── Status message ── */
      .status-banner {
        display: none;
        align-items: center;
        gap: .625rem;
        padding: .875rem 1rem;
        border-radius: var(--radius-md);
        font-size: .9375rem;
        font-weight: 500;
        margin-top: 1.25rem;
      }
      .status-banner.success {
        display: flex;
        background: var(--color-success-bg);
        border: 1.5px solid var(--color-success-border);
        color: var(--color-success);
      }
      .status-banner svg { flex-shrink: 0; }

      /* ── Footer ── */
      footer {
        padding: 1.25rem 1.5rem;
        text-align: center;
        font-size: .8125rem;
        color: var(--color-text-muted);
        border-top: 1px solid var(--color-border);
      }

      /* ── Forced Colors ── */
      @media (forced-colors: active) {
        .form-field input[type="checkbox"]:checked { forced-color-adjust: none; }
        .btn-submit { border: 2px solid ButtonText; }
      }

      /* ── Reduced motion ── */
      @media (prefers-reduced-motion: reduce) {
        *, *::before, *::after { transition-duration: .01ms !important; }
      }

      /* ── Reflow / narrow viewports ── */
      @media (max-width: 380px) {
        .card { padding: 1.75rem 1.125rem; }
        .card-header h1 { font-size: 1.25rem; }
      }
    </style>
  </head>
  <body>

    <!-- Skip navigation -->
    <a class="skip-link" href="#main-content">Skip to main content</a>

    <header>
      <a class="brand" href="#">Acme&nbsp;Corp</a>
    </header>

    <main id="main-content">
      <div class="card" role="region" aria-label="Terms of use agreement">

        <div class="card-header">
          <h1>Terms of Use</h1>
          <p>Please review and accept our terms before continuing.</p>
        </div>

        <p class="required-legend">
          Fields marked <span aria-hidden="true">*</span>
          <span class="sr-only">with an asterisk</span> are required.
        </p>

        <form id="consent-form" novalidate>

          <!-- Consent checkbox -->
          <div
            class="form-field"
            id="agree-field"
          >
            <input
              type="checkbox"
              id="agree-terms"
              name="agree"
              required
              aria-required="true"
              aria-describedby="agree-helper agree-error"
            />
            <label for="agree-terms">
              I have read and agree to the
              <a href="/terms" target="_blank" rel="noopener noreferrer">Terms of Use</a>
              and
              <a href="/privacy" target="_blank" rel="noopener noreferrer">Privacy Policy</a>.<span
                class="required-star"
                aria-hidden="true"
              >*</span>
            </label>
          </div>

          <p id="agree-helper" class="field-helper">
            You must accept the terms to create your account.
          </p>

          <!-- Error (hidden until validation fires) -->
          <p id="agree-error" class="field-error" aria-live="assertive" hidden>
            <svg
              aria-hidden="true"
              focusable="false"
              width="16" height="16"
              viewBox="0 0 16 16"
              fill="none"
            >
              <circle cx="8" cy="8" r="7.25" stroke="currentColor" stroke-width="1.5"/>
              <path d="M8 4.5v4" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"/>
              <circle cx="8" cy="11" r=".75" fill="currentColor"/>
            </svg>
            Error: You must agree to the terms to continue.
          </p>

          <button type="submit" class="btn-submit">
            Accept &amp; Continue
          </button>

          <!-- Success status -->
          <div
            id="success-banner"
            class="status-banner"
            role="status"
            aria-live="polite"
          >
            <svg
              aria-hidden="true"
              focusable="false"
              width="18" height="18"
              viewBox="0 0 18 18"
              fill="none"
            >
              <circle cx="9" cy="9" r="8.25" stroke="currentColor" stroke-width="1.5"/>
              <path d="M5.5 9l2.5 2.5 4.5-5" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round"/>
            </svg>
            Your agreement has been recorded. Welcome!
          </div>

        </form>

      </div>
    </main>

    <footer>
      &copy; 2026 Acme&nbsp;Corp. All rights reserved.
    </footer>

    <!-- Screen-reader-only utility class -->
    <style>
      .sr-only {
        position: absolute;
        width: 1px; height: 1px;
        padding: 0; margin: -1px;
        overflow: hidden;
        clip: rect(0,0,0,0);
        white-space: nowrap;
        border: 0;
      }
    </style>

    <script>
      (function () {
        "use strict";

        const form       = document.getElementById("consent-form");
        const checkbox   = document.getElementById("agree-terms");
        const field      = document.getElementById("agree-field");
        const errorMsg   = document.getElementById("agree-error");
        const successBanner = document.getElementById("success-banner");

        function setInvalid() {
          checkbox.setAttribute("aria-invalid", "true");
          field.classList.add("is-invalid");
          errorMsg.hidden = false;
        }

        function clearInvalid() {
          checkbox.removeAttribute("aria-invalid");
          field.classList.remove("is-invalid");
          errorMsg.hidden = true;
        }

        // Clear error as soon as the user checks the box
        checkbox.addEventListener("change", function () {
          if (this.checked) clearInvalid();
        });

        form.addEventListener("submit", function (e) {
          e.preventDefault();

          if (!checkbox.checked) {
            setInvalid();
            checkbox.focus();   // move focus to first invalid control
            return;
          }

          // Happy path
          clearInvalid();
          successBanner.classList.add("success");

          // Disable the form to prevent double-submit
          checkbox.disabled = true;
          form.querySelector(".btn-submit").disabled = true;
        });
      })();
    </script>

  </body>
</html>
