    <style>
      /* ── Reset & tokens ── */
      *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

      :root {
        --color-bg:           #f5f5f7;
        --color-surface:      #ffffff;
        --color-border:       #d1d5db;
        --color-border-focus: #2563eb;
        --color-primary:      #2563eb;
        --color-primary-dark: #1d4ed8;
        --color-text:         #111827;
        --color-text-muted:   #6b7280;
