       .status-banner svg { flex-shrink: 0; }

       /* ── Footer ── */
       footer {
         padding: 1.25rem 1.5rem;
         text-align: center;
         font-size: .8125rem;
         color: var(--color-text-muted);
         background: var(--color-surface); /* ensures #6b7280 on #fff passes 4.5:1 */
         border-top: 1px solid var(--color-border);
       }

       /* ── Forced Colors ── */
       @media (forced-colors: active) {
         .form-field input[type="checkbox"]:checked { forced-color-adjust: none; }
         .btn-submit { border: 2px solid ButtonText; }
       }

       /* ── Reduced motion ── */
       @media (prefers-reduced-motion: reduce) {
         *, *::before, *::after { transition-duration: .01ms !important; }
       }

       /* ── Reflow / narrow viewports ── */
       @media (max-width: 380px) {
         .card { padding: 1.75rem 1.125rem; }
         .card-header h1 { font-size: 1.25rem; }
       }
