         <form id="consent-form" novalidate>

           <!-- Consent checkbox -->
           <div
             class="form-field"
             id="agree-field"
           >
             <input
               type="checkbox"
               id="agree-terms"
               name="agree"
               required
               aria-required="true"
               aria-describedby="agree-helper agree-error"
             />
             <label for="agree-terms">
               I have read and agree to the
               <a href="/terms" target="_blank" rel="noopener noreferrer">Terms of Use</a>
