               viewBox="0 0 18 18"
               fill="none"
             >
               <circle cx="9" cy="9" r="8.25" stroke="currentColor" stroke-width="1.5"/>
               <path d="M5.5 9l2.5 2.5 4.5-5" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round"/>
